'use client';

import { useEffect, useRef } from 'react';

export function ElegantBackground() {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    // Emerald dust particles
    interface Particle {
      x: number;
      y: number;
      size: number;
      speedX: number;
      speedY: number;
      opacity: number;
      twinkleSpeed: number;
      twinklePhase: number;
    }

    const particles: Particle[] = [];
    const particleCount = 35;

    for (let i = 0; i < particleCount; i++) {
      particles.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        size: Math.random() * 1.2 + 0.2,
        speedX: (Math.random() - 0.5) * 0.08,
        speedY: -Math.random() * 0.1 - 0.02,
        opacity: Math.random() * 0.3 + 0.05,
        twinkleSpeed: Math.random() * 0.012 + 0.003,
        twinklePhase: Math.random() * Math.PI * 2,
      });
    }

    // Subtle orbs
    const orbs = [
      { x: 0.25, y: 0.3, r: 380, color: [52, 211, 153], speed: 0.0002, phase: 0, maxOpacity: 0.025 },
      { x: 0.75, y: 0.35, r: 320, color: [45, 212, 191], speed: 0.00025, phase: 2, maxOpacity: 0.02 },
      { x: 0.5, y: 0.7, r: 400, color: [52, 211, 153], speed: 0.00015, phase: 4, maxOpacity: 0.02 },
    ];

    let time = 0;

    const animate = () => {
      time += 0.016;
      const w = canvas.width;
      const h = canvas.height;

      // Deep slate background — NOT black
      const bgGrad = ctx.createRadialGradient(w * 0.5, h * 0.4, 0, w * 0.5, h * 0.5, w * 0.8);
      bgGrad.addColorStop(0, '#151d2e');
      bgGrad.addColorStop(1, '#111827');
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0, 0, w, h);

      // Draw orbs
      orbs.forEach(orb => {
        const ox = orb.x * w + Math.sin(time * orb.speed * 800 + orb.phase) * 35;
        const oy = orb.y * h + Math.cos(time * orb.speed * 600 + orb.phase) * 25;
        const gradient = ctx.createRadialGradient(ox, oy, 0, ox, oy, orb.r);
        gradient.addColorStop(0, `rgba(${orb.color[0]}, ${orb.color[1]}, ${orb.color[2]}, ${orb.maxOpacity})`);
        gradient.addColorStop(0.5, `rgba(${orb.color[0]}, ${orb.color[1]}, ${orb.color[2]}, ${orb.maxOpacity * 0.3})`);
        gradient.addColorStop(1, 'transparent');
        ctx.beginPath();
        ctx.arc(ox, oy, orb.r, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();
      });

      // Emerald dust particles
      particles.forEach(p => {
        p.x += p.speedX;
        p.y += p.speedY;
        p.twinklePhase += p.twinkleSpeed;

        if (p.x < 0) p.x = w;
        if (p.x > w) p.x = 0;
        if (p.y < 0) p.y = h;
        if (p.y > h) p.y = 0;

        const twinkle = (Math.sin(p.twinklePhase) + 1) * 0.5;
        const alpha = p.opacity * (0.2 + twinkle * 0.8);

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(52, 211, 153, ${alpha})`;
        ctx.fill();

        if (p.size > 0.8) {
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size * 3, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(52, 211, 153, ${alpha * 0.06})`;
          ctx.fill();
        }
      });

      requestAnimationFrame(animate);
    };

    const id = requestAnimationFrame(animate);
    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(id);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 z-0"
      style={{ pointerEvents: 'none' }}
    />
  );
}
