'use client';

import { useEffect, useState, useCallback } from 'react';
import { Plus, Trash2, Check, X, Clock, AlertCircle, Filter, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { todoService, type TodoFilters } from '@/services';
import type { Todo } from '@prisma/client';
import { ElegantBackground } from '@/components/ElegantBackground';

const priorityConfig = {
  low: { label: 'پایین', color: 'secondary', icon: null },
  medium: { label: 'متوسط', color: 'default', icon: null },
  high: { label: 'بالا', color: 'destructive', icon: AlertCircle },
  critical: { label: 'بحرانی', color: 'destructive', icon: AlertCircle },
};

const statusConfig = {
  pending: { label: 'در انتظار', color: 'secondary' },
  in_progress: { label: 'در حال انجام', color: 'default' },
  completed: { label: 'تکمیل شده', color: 'outline' },
  archived: { label: 'بایگانی شده', color: 'secondary' },
};

const categoryLabels: Record<string, string> = {
  backend: 'بک‌اند',
  frontend: 'فرانت‌اند',
  database: 'دیتابیس',
  api: 'API',
  ui: 'رابط کاربری',
  testing: 'تست',
  documentation: 'مستندات',
  general: 'عمومی',
};

export default function TodosPage() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [statistics, setStatistics] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingTodo, setEditingTodo] = useState<Todo | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    status: 'pending',
    priority: 'medium',
    category: 'general',
    tags: '',
    dueDate: '',
  });

  const [filters, setFilters] = useState<TodoFilters>({});

  const loadTodos = useCallback(async () => {
    setLoading(true);
    try {
      const result = await fetch('/api/todos' + new URLSearchParams(filters as any).toString());
      const json = await result.json();
      if (json.success) {
        setTodos(json.data);
        setStatistics(json.statistics);
      }
    } catch (error) {
      console.error('خطا در بارگذاری todos:', error);
    } finally {
      setLoading(false);
    }
  }, [filters]);

  useEffect(() => {
    loadTodos();
  }, [loadTodos]);

  const openCreate = () => {
    setEditingTodo(null);
    setFormData({
      title: '',
      description: '',
      status: 'pending',
      priority: 'medium',
      category: 'general',
      tags: '',
      dueDate: '',
    });
    setDialogOpen(true);
  };

  const openEdit = (todo: Todo) => {
    setEditingTodo(todo);
    setFormData({
      title: todo.title,
      description: todo.description || '',
      status: todo.status,
      priority: todo.priority,
      category: todo.category,
      tags: Array.isArray(todo.tags) ? todo.tags.join(', ') : '',
      dueDate: todo.dueDate ? new Date(todo.dueDate).toISOString().slice(0, 10) : '',
    });
    setDialogOpen(true);
  };

  const handleSubmit = async () => {
    if (!formData.title.trim()) return;

    const payload: any = {
      title: formData.title.trim(),
      description: formData.description.trim() || undefined,
      status: formData.status,
      priority: formData.priority,
      category: formData.category,
      tags: formData.tags ? formData.tags.split(',').map(t => t.trim()).filter(Boolean) : undefined,
      dueDate: formData.dueDate || undefined,
    };

    if (editingTodo) {
      payload.completedAt = formData.status === 'completed' && !editingTodo.completedAt
        ? new Date().toISOString()
        : formData.status !== 'completed'
          ? null
          : editingTodo.completedAt ? new Date(editingTodo.completedAt).toISOString() : undefined;
    }

    const url = editingTodo ? `/api/todos/${editingTodo.id}` : '/api/todos';
    const method = editingTodo ? 'PUT' : 'POST';

    try {
      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (json.success) {
        setDialogOpen(false);
        loadTodos();
      }
    } catch (error) {
      console.error('خطا در ذخیره todo:', error);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const res = await fetch(`/api/todos/${id}`, { method: 'DELETE' });
      const json = await res.json();
      if (json.success) {
        setDeleteConfirm(null);
        loadTodos();
      }
    } catch (error) {
      console.error('خطا در حذف todo:', error);
    }
  };

  const toggleStatus = async (todo: Todo) => {
    const next = todo.status === 'completed' ? 'pending' : 'completed';
    await fetch(`/api/todos/${todo.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        status: next,
        completedAt: next === 'completed' ? new Date().toISOString() : null,
      }),
    });
    loadTodos();
  };

  const formatDate = (date: string | Date | null | undefined) => {
    if (!date) return '-';
    return new Date(date).toLocaleDateString('fa-IR');
  };

  const isOverdue = (todo: Todo) => {
    if (!todo.dueDate || todo.status === 'completed') return false;
    return new Date(todo.dueDate) < new Date();
  };

  return (
    <div className="min-h-screen flex flex-col bg-background relative">
      <ElegantBackground />

      <header className="border-b border-border bg-background/90 backdrop-blur-xl sticky top-0 z-40">
        <div className="container mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-foreground">لیست Todo</h1>
              <p className="text-sm text-muted-foreground">مدیریت کارهای باقیمانده پروژه</p>
            </div>
            <Button onClick={openCreate} className="gap-2">
              <Plus className="size-4" />
              Todo جدید
            </Button>
          </div>
        </div>
      </header>

      <main className="flex-1 container mx-auto px-4 py-6 relative z-10">
        {statistics && (
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-4 mb-6">
            <Card>
              <CardContent className="p-4">
                <div className="text-2xl font-bold">{statistics.total}</div>
                <div className="text-xs text-muted-foreground">کل Todoها</div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4">
                <div className="text-2xl font-bold text-yellow-600">{statistics.pending}</div>
                <div className="text-xs text-muted-foreground">در انتظار</div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4">
                <div className="text-2xl font-bold text-blue-600">{statistics.inProgress}</div>
                <div className="text-xs text-muted-foreground">در حال انجام</div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4">
                <div className="text-2xl font-bold text-green-600">{statistics.completed}</div>
                <div className="text-xs text-muted-foreground">تکمیل شده</div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 col-span-2 sm:col-span-1">
                <div className="text-2xl font-bold text-red-600">{statistics.overdue}</div>
                <div className="text-xs text-muted-foreground">منقضی شده</div>
              </CardContent>
            </Card>
          </div>
        )}

        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Filter className="size-4" />
              فیلترها
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex flex-wrap gap-3">
              <div className="flex-1 min-w-[200px]">
                <div className="relative">
                  <Search className="absolute right-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
                  <Input
                    placeholder="جستجو..."
                    className="pr-9"
                    value={filters.search || ''}
                    onChange={(e) => setFilters({ ...filters, search: e.target.value })}
                  />
                </div>
              </div>
              <Select
                value={filters.status || 'all'}
                onValueChange={(value) => setFilters({ ...filters, status: value === 'all' ? undefined : value })}
              >
                <SelectTrigger className="w-[140px]">
                  <SelectValue placeholder="وضعیت" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">همه وضعیت‌ها</SelectItem>
                  <SelectItem value="pending">در انتظار</SelectItem>
                  <SelectItem value="in_progress">در حال انجام</SelectItem>
                  <SelectItem value="completed">تکمیل شده</SelectItem>
                  <SelectItem value="archived">بایگانی شده</SelectItem>
                </SelectContent>
              </Select>

              <Select
                value={filters.priority || 'all'}
                onValueChange={(value) => setFilters({ ...filters, priority: value === 'all' ? undefined : value })}
              >
                <SelectTrigger className="w-[140px]">
                  <SelectValue placeholder="اولویت" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">همه اولویت‌ها</SelectItem>
                  <SelectItem value="critical">بحرانی</SelectItem>
                  <SelectItem value="high">بالا</SelectItem>
                  <SelectItem value="medium">متوسط</SelectItem>
                  <SelectItem value="low">پایین</SelectItem>
                </SelectContent>
              </Select>

              <Select
                value={filters.category || 'all'}
                onValueChange={(value) => setFilters({ ...filters, category: value === 'all' ? undefined : value })}
              >
                <SelectTrigger className="w-[160px]">
                  <SelectValue placeholder="دسته‌بندی" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">همه دسته‌ها</SelectItem>
                  <SelectItem value="backend">بک‌اند</SelectItem>
                  <SelectItem value="frontend">فرانت‌اند</SelectItem>
                  <SelectItem value="database">دیتابیس</SelectItem>
                  <SelectItem value="api">API</SelectItem>
                  <SelectItem value="ui">رابط کاربری</SelectItem>
                  <SelectItem value="testing">تست</SelectItem>
                  <SelectItem value="documentation">مستندات</SelectItem>
                  <SelectItem value="general">عمومی</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Todoها ({todos.length})</CardTitle>
          </CardHeader>
          <CardContent>
            {loading ? (
              <div className="text-center py-8 text-muted-foreground">در حال بارگذاری...</div>
            ) : todos.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">هیچ todoyی پیدا نشد</div>
            ) : (
              <div className="border rounded-lg overflow-hidden">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-[40px]">#</TableHead>
                      <TableHead>عنوان</TableHead>
                      <TableHead className="w-[100px]">دسته‌بندی</TableHead>
                      <TableHead className="w-[100px]">وضعیت</TableHead>
                      <TableHead className="w-[90px]">اولویت</TableHead>
                      <TableHead className="w-[100px]">مهلت</TableHead>
                      <TableHead className="w-[100px]">ایجاد</TableHead>
                      <TableHead className="w-[120px] text-left">عملیات</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {todos.map((todo) => {
                      const statusConf = statusConfig[todo.status] || statusConfig.pending;
                      const priorityConf = priorityConfig[todo.priority] || priorityConfig.medium;
                      const overdue = isOverdue(todo);

                      return (
                        <TableRow key={todo.id} className={overdue ? 'bg-red-50/50 dark:bg-red-950/20' : ''}>
                          <TableCell className="text-muted-foreground text-xs">
                            {new Date(todo.createdAt).toLocaleDateString('fa-IR')}
                          </TableCell>
                          <TableCell>
                            <div className="flex flex-col gap-1">
                              <span className={`font-medium ${todo.status === 'completed' ? 'line-through text-muted-foreground' : ''}`}>
                                {todo.title}
                              </span>
                              {todo.description && (
                                <span className="text-xs text-muted-foreground line-clamp-1">
                                  {todo.description}
                                </span>
                              )}
                              {overdue && (
                                <span className="text-xs text-red-600 flex items-center gap-1">
                                  <AlertCircle className="size-3" />
                                  منقضی شده
                                </span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell>
                            <Badge variant="outline" className="text-xs">
                              {categoryLabels[todo.category] || todo.category}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <Badge variant={statusConf.color as any} className="text-xs">
                              {statusConf.label}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <Badge variant={priorityConf.color as any} className="text-xs gap-1">
                              {priorityConf.label}
                            </Badge>
                          </TableCell>
                          <TableCell className={`text-xs ${overdue ? 'text-red-600 font-medium' : ''}`}>
                            {formatDate(todo.dueDate)}
                          </TableCell>
                          <TableCell className="text-xs text-muted-foreground">
                            {formatDate(todo.createdAt)}
                          </TableCell>
                          <TableCell>
                            <div className="flex items-center gap-1">
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-8"
                                onClick={() => toggleStatus(todo)}
                                title={todo.status === 'completed' ? 'بازنشانی' : 'تکمیل'}
                              >
                                <Check className="size-4 text-green-600" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-8"
                                onClick={() => openEdit(todo)}
                              >
                                <Clock className="size-4 text-blue-600" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-8"
                                onClick={() => setDeleteConfirm(todo.id)}
                              >
                                <Trash2 className="size-4 text-red-600" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </div>
            )}
          </CardContent>
        </Card>
      </main>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingTodo ? 'ویرایش Todo' : 'Todo جدید'}</DialogTitle>
            <DialogDescription>
              {editingTodo ? 'اطلاعات todo را ویرایش کنید' : 'یک todo جدید برای کارهای باقیمانده ایجاد کنید'}
            </DialogDescription>
          </DialogHeader>

          <div className="flex flex-col gap-4">
            <div>
              <label className="text-sm font-medium mb-1.5 block">عنوان *</label>
              <Input
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                placeholder="عنوان کار را وارد کنید..."
              />
            </div>

            <div>
              <label className="text-sm font-medium mb-1.5 block">توضیحات</label>
              <Textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="توضیحات اختیاری..."
                rows={3}
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-sm font-medium mb-1.5 block">وضعیت</label>
                <Select value={formData.status} onValueChange={(value) => setFormData({ ...formData, status: value as any })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="pending">در انتظار</SelectItem>
                    <SelectItem value="in_progress">در حال انجام</SelectItem>
                    <SelectItem value="completed">تکمیل شده</SelectItem>
                    <SelectItem value="archived">بایگانی شده</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <label className="text-sm font-medium mb-1.5 block">اولویت</label>
                <Select value={formData.priority} onValueChange={(value) => setFormData({ ...formData, priority: value as any })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">پایین</SelectItem>
                    <SelectItem value="medium">متوسط</SelectItem>
                    <SelectItem value="high">بالا</SelectItem>
                    <SelectItem value="critical">بحرانی</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <label className="text-sm font-medium mb-1.5 block">دسته‌بندی</label>
                <Select value={formData.category} onValueChange={(value) => setFormData({ ...formData, category: value as any })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="general">عمومی</SelectItem>
                    <SelectItem value="backend">بک‌اند</SelectItem>
                    <SelectItem value="frontend">فرانت‌اند</SelectItem>
                    <SelectItem value="database">دیتابیس</SelectItem>
                    <SelectItem value="api">API</SelectItem>
                    <SelectItem value="ui">رابط کاربری</SelectItem>
                    <SelectItem value="testing">تست</SelectItem>
                    <SelectItem value="documentation">مستندات</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <label className="text-sm font-medium mb-1.5 block">مهلت</label>
                <Input
                  type="date"
                  value={formData.dueDate}
                  onChange={(e) => setFormData({ ...formData, dueDate: e.target.value })}
                />
              </div>
            </div>

            <div>
              <label className="text-sm font-medium mb-1.5 block">تگ‌ها (جدا شده با ویرگول)</label>
              <Input
                value={formData.tags}
                onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
                placeholder="مثلاً: مهم، سریع، cleanup"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              <X className="size-4 ml-1" />
              لغو
            </Button>
            <Button onClick={handleSubmit}>
              <Check className="size-4 ml-1" />
              {editingTodo ? 'ذخیره تغییرات' : 'ایجاد Todo'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={!!deleteConfirm} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>تایید حذف</DialogTitle>
            <DialogDescription>
              آیا از حذف این todo اطمینان دارید؟ این عمل قابل بازگشت نیست.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteConfirm(null)}>
              لغو
            </Button>
            <Button variant="destructive" onClick={() => deleteConfirm && handleDelete(deleteConfirm)}>
              حذف
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}